import{_ as p,a0 as l,w as o,s as d,ao as r,I as n,x as t,a1 as a,A as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"如何发现截断的数据项 | LCTT x X-CMD","titleTemplate":false,"description":"如何发现截断的数据项 | LCTT (201909) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何发现截断的数据项 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何发现截断的数据项 | LCTT (201909) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201909/20180704 BASHing data- Truncated data items","title":"如何发现截断的数据项","tag":"201909","desc":""},"relativePath":"201909/20180704 BASHing data- Truncated data items.md","filePath":"[post].md"}'),g={name:"201909/20180704 BASHing data- Truncated data items.md"};function h(u,s,c,k,m,b){const i=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="如何发现截断的数据项" tabindex="-1">如何发现截断的数据项 <a class="header-anchor" href="#如何发现截断的数据项" aria-label="Permalink to “如何发现截断的数据项”">​</a></h1><p><strong>截断</strong>（形容词）：缩写、删节、缩减、剪切、剪裁、裁剪、修剪……</p><p>数据项被截断的一种情况是将其输入到数据库字段中，该字段的字符限制比数据项的长度要短。例如，字符串：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Yarrow Ravine Rattlesnake Habitat Area, 2 mi ENE of Yermo CA</span></span></code></pre></div><p>是 60 个字符长。如果你将其输入到具有 50 个字符限制的“位置”字段，则可以获得：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Yarrow Ravine Rattlesnake Habitat Area, 2 mi ENE #末尾带有一个空格</span></span></code></pre></div><p>截断也可能导致数据错误，比如你打算输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sally Ann Hunter (aka Sally Cleveland)</span></span></code></pre></div><p>但是你忘记了闭合的括号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Sally Ann Hunter (aka Sally Cleveland</span></span></code></pre></div><p>这会让使用数据的用户觉得 Sally 是否有被修剪掉了数据项的其它的别名。</p><p>截断的数据项很难检测。在审核数据时，我使用三种不同的方法来查找可能的截断，但我仍然可能会错过一些。</p><p><strong>数据项的长度分布。</strong>第一种方法是捕获我在各个字段中找到的大多数截断的数据。我将字段传递给 <code>awk</code> 命令，该命令按字段宽度计算数据项，然后我使用 <code>sort</code> 以宽度的逆序打印计数。例如，要检查以 <code>tab</code> 分隔的文件 <code>midges</code> 中的第 33 个字段：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk -F&quot;\\t&quot; &#39;NR&gt;1 {a[length($33)]++} \\</span></span>
<span class="line"><span>    END {for (i in a) print i FS a[i]}&#39; midges | sort -nr</span></span></code></pre></div><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_1.png" alt="distro1"></p><p>最长的条目恰好有 50 个字符，这是可疑的，并且在该宽度处存在数据项的“凸起”，这更加可疑。检查这些 50 个字符的项目会发现截断：</p><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_2.png" alt="distro2"></p><p>我用这种方式检查的其他数据表有 100、200 和 255 个字符的“凸起”。在每种情况下，这种“凸起”都包含明显的截断。</p><p><strong>未匹配的括号。</strong>第二种方法查找类似 <code>...(Sally Cleveland</code> 的数据项。一个很好的起点是数据表中所有标点符号的统计。这里我检查文件 <code>mag2</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>grep -o &quot;[[:punct:]]&quot; file | sort | uniqc</span></span></code></pre></div><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_3.png" alt="punct"></p><p>请注意，<code>mag2</code> 中的开括号和闭括号的数量不相等。要查看发生了什么，我使用 <code>unmatched</code> 函数，它接受三个参数并检查数据表中的所有字段。第一个参数是文件名，第二个和第三个是开括号和闭括号，用引号括起来。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>unmatched()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    awk -F&quot;\\t&quot; -v start=&quot;$2&quot; -v end=&quot;$3&quot; \\</span></span>
<span class="line"><span>        &#39;{for (i=1;i&lt;=NF;i++) \\</span></span>
<span class="line"><span>            if (split($i,a,start) != split($i,b,end)) \\</span></span>
<span class="line"><span>                print &quot;line &quot;NR&quot;, field &quot;i&quot;:\\n&quot;$i}&#39; &quot;$1&quot;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>如果在字段中找到开括号和闭括号之间不匹配，则 <code>unmatched</code> 会报告行号和字段号。这依赖于 <code>awk</code> 的 <code>split</code> 函数，它返回由分隔符分隔的元素数（包括空格）。这个数字总是比分隔符的数量多一个：</p><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_4.png" alt="split"></p><p>这里 <code>ummatched</code> 检查 <code>mag2</code> 中的圆括号并找到一些可能的截断：</p><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_5.png" alt="unmatched"></p><p>我使用 <code>unmatched</code> 来找到不匹配的圆括号 <code>()</code>、方括号 <code>[]</code>、花括号 <code>{}</code> 和尖括号 <code>&lt;&gt;</code>，但该函数可用于任何配对的标点字符。</p><p><strong>意外的结尾。</strong>第三种方法查找以尾随空格或非终止标点符号结尾的数据项，如逗号或连字符。这可以在单个字段上用 <code>cut</code> 用管道输入到 <code>grep</code> 完成，或者用 <code>awk</code> 一步完成。在这里，我正在检查以制表符分隔的表 <code>herp5</code> 的字段 47，并提取可疑数据项及其行号：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cut -f47 herp5 | grep -n &quot;[ ,;:-]$&quot;</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>awk -F&quot;\\t&quot; &#39;$47 ~ /[ ,;:-]$/ {print NR&quot;: &quot;$47}&#39; herp5</span></span></code></pre></div><p><img src="https://www.polydesmida.info/BASHing/img1/2018-07-04_6.png" alt="herps5"></p><p>用于制表符分隔文件的 awk 命令的全字段版本是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk -F&quot;\\t&quot; &#39;{for (i=1;i&lt;=NF;i++) if ($i ~ /[ ,;:-]$/) \\</span></span>
<span class="line"><span>    print &quot;line &quot;NR&quot;, field &quot;i&quot;:\\n&quot;$i}&#39; file</span></span></code></pre></div><p><strong>谨慎的想法。</strong>在我对字段进行的验证测试期间也会出现截断。例如，我可能会在“年”的字段中检查合理的 4 位数条目，并且有个 <code>198</code> 可能是 198n？还是 1898 年？带有丢失字符的截断数据项是个谜。 作为数据审计员，我只能报告（可能的）字符损失，并建议数据编制者或管理者恢复（可能）丢失的字符。</p><hr>`,35)),n("p",null,[s[1]||(s[1]=t("via: ",-1)),a(i,{href:"https://www.polydesmida.info/BASHing/2018-07-04.html"},{default:e(()=>[...s[0]||(s[0]=[t("https://www.polydesmida.info/BASHing/2018-07-04.html",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=t("作者：",-1)),a(i,{href:"https://www.polydesmida.info/"},{default:e(()=>[...s[2]||(s[2]=[t("polydesmida",-1)])]),_:1}),s[7]||(s[7]=t(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:e(()=>[...s[3]||(s[3]=[t("lujun9972",-1)])]),_:1}),s[8]||(s[8]=t(" 译者：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[4]||(s[4]=[t("wxy",-1)])]),_:1}),s[9]||(s[9]=t(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:e(()=>[...s[5]||(s[5]=[t("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[10]||(s[10]=[t("LCTT",-1)])]),_:1}),s[13]||(s[13]=t(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:e(()=>[...s[11]||(s[11]=[t("Linux中国",-1)])]),_:1}),s[14]||(s[14]=t(" 荣誉推出",-1))])])}const C=p(g,[["render",h]]);export{w as __pageData,C as default};
